/usr/bin/bash -lc "set -euo pipefail
required_columns='bioproject run_accession study_accession experiment_accession sample_accession biosample organism_taxid organism_name library_strategy library_source library_selection library_layout instrument_model run_total_spots run_total_bases'
for project in PRJNA1354216 PRJNA1339024; do
  metadata=\"final_answer/metadata/"'${project}.tsv"
  awk -F '"'\\t' -v project=\""'$project" -v required="$required_columns" '"'
    NR==1 {
      for (i=1; i<=NF; i++) col["'$i]=i
      n=split(required, req, " ")
      for (i=1; i<=n; i++) if (!(req[i] in col)) {print "missing column " req[i] > "/dev/stderr"; exit 10}
      next
    }
